// Spider fusion: merge a vertex-disjoint MATCHING of same-coloured spiders
// joined by SIMPLE wires in one query; the driver loops to a fixpoint.
//
// The matching is the MUTUAL-MINIMUM-NEIGHBOUR handshake â€” an edge (a,b) is
// kept iff a's smallest-id same-colour simple neighbour is b AND b's is a.
// Such pairs are vertex-disjoint (each node is the mutual minimum of at
// most one edge), so they fuse simultaneously; and the globally smallest
// fusable endpoint with its smallest neighbour is always such a pair, so
// at least one edge is selected whenever any fusable edge exists (the
// driver loop makes progress). The minimum neighbour is computed in ONE
// aggregation pass (O(E)) instead of the previous O(E^2) `reduce` over an
// accumulating node list, and the edge is processed from its smaller
// endpoint so each matched pair appears exactly once.

MATCH (a:Node {graph_id: $graph_id})-[:Wire {t: 1}]-(n:Node)
WHERE a.t = n.t AND a.t IN [1, 2]
WITH a, min(id(n)) AS amin
MATCH (a)-[:Wire {t: 1}]-(b:Node)
WHERE id(b) = amin AND id(a) < id(b)
MATCH (b)-[:Wire {t: 1}]-(nb:Node)
WHERE nb.t = b.t AND nb.t IN [1, 2]
WITH a, b, min(id(nb)) AS bmin
WHERE bmin = id(a)
WITH a AS u, b AS v

// Create the merged node with summed phase (unchanged).
CREATE (merged:Node {
  phase: (coalesce(u.phase, 0) + coalesce(v.phase, 0)) % 2,
  t: u.t,
  graph_id: u.graph_id
})
WITH DISTINCT u, v, merged

// Reconnect neighbors of u and v to merged.
OPTIONAL MATCH (u)-[r:Wire]-(x)
WHERE x <> v
FOREACH (_ IN CASE WHEN x IS NOT NULL THEN [1] ELSE [] END |
  CREATE (merged)-[:Wire {t: r.t , graph_id: r.graph_id}]->(x)
)

WITH DISTINCT u, v, merged
OPTIONAL MATCH (v)-[r:Wire]-(y)
WHERE y <> u
FOREACH (_ IN CASE WHEN y IS NOT NULL THEN [1] ELSE [] END |
  CREATE (merged)-[:Wire {t: r.t , graph_id: r.graph_id}]->(y)
)

DETACH DELETE u, v

RETURN COUNT(*) AS merged

// Hopf: pairs of SIMPLE wires between opposite-colored spiders cancel.
// Hadamard wires must be left for color-aware parallel-edge normalization.
MATCH (n1:Node {graph_id: $graph_id, t: 1})-[w:Wire {t: 1}]-(n2:Node {t: 2})
WITH n1, n2, collect(w) AS wires, count(w) AS n_wires

// Calculate how many to keep (either 0 or 1)
WITH n1, n2, wires, n_wires, n_wires % 2 AS keep_n
// Get the wires to delete
WITH wires[..(n_wires - keep_n)] AS wires_to_delete
UNWIND wires_to_delete AS w_to_delete
DELETE w_to_delete

// Find inclusion-wise maximal bipartite cliques where t=1 and t=2
MATCH (seed {graph_id: $graph_id})
WHERE seed.t = 1
OPTIONAL MATCH (seed {graph_id: $graph_id})-[r]-(b)
WHERE b.t = 2 AND r.t = 1
WITH seed, collect(DISTINCT b) AS B
WHERE size(B) > 0

// Find all t=1 nodes connected to ALL nodes in B
MATCH (x {graph_id: $graph_id})
WHERE x.t = 1
OPTIONAL MATCH (x {graph_id: $graph_id})-[r]-(b2)
WHERE b2 IN B AND r.t = 1
WITH B, x, count(DISTINCT b2) AS cnt_connected
WHERE cnt_connected = size(B)

// Collect closure
WITH B, collect(DISTINCT x) AS A
WHERE size(B) + size(A) > 2

// Compute degree constraint
WITH A, B, A + B AS allNodes
UNWIND allNodes AS n
// Count all edges of type t=1
OPTIONAL MATCH (n {graph_id: $graph_id})-[r1]-(m)
WHERE r1.t = 1
WITH A, B, allNodes, n, count(DISTINCT m) AS total_edges

// Count edges of type t=1 that connect inside the clique
OPTIONAL MATCH (n {graph_id: $graph_id})-[r2]-(m2)
WHERE r2.t = 1 AND m2 IN allNodes
WITH A, B, allNodes, n, total_edges, count(DISTINCT m2) AS clique_edges

// Keep nodes where exactly one edge is outside the clique
WITH A, B, allNodes, collect(
  CASE WHEN total_edges - clique_edges = 1 THEN n ELSE NULL END
) AS valid_nodes
WHERE size(valid_nodes) = size(allNodes)
  AND ALL(n IN allNodes WHERE n.phase IS NOT NULL AND n.phase % 2 = 0
    AND degree(n) = size(CASE WHEN n.t = 1 THEN B ELSE A END) + 1)

WITH [n IN (A + B) | id(n)] AS cliqueNodeIds
WITH DISTINCT cliqueNodeIds AS cliqueNodeIds         // ensure unique candidate cliques

// For each clique, compute the flattened neighbor id list (excluding internal nodes)
WITH collect(cliqueNodeIds) AS allCliquesIds
UNWIND allCliquesIds AS cliqueIds

// get every neighbor id of nodes in this clique
UNWIND cliqueIds AS nid
MATCH (n {graph_id: $graph_id}) WHERE id(n) = nid
OPTIONAL MATCH (n {graph_id: $graph_id})-[]-(nbr)
WITH cliqueIds, collect(DISTINCT id(nbr)) AS allNbrs

// remove internal ids (nodes of the clique) from neighbor list
WITH cliqueIds, [x IN allNbrs WHERE NOT x IN cliqueIds] AS neighborIds

// represent clique as a map of ids + neighbors
WITH collect({nodes: cliqueIds, neighbors: neighborIds}) AS allCliques
//RETURN allCliques
// --- Phase 3: pick disjoint cliques using reduce over id-lists ---
WITH allCliques
WITH reduce(acc = {cliques: [], nodes: [], neigh: []}, clique IN allCliques |
  CASE
    WHEN
      // ensure candidate clique has no node in accepted nodes (no overlap)
      NONE (nid IN clique.nodes WHERE nid IN acc.nodes)
      AND
      // ensure no candidate node is adjacent to any accepted node
      NONE (nid IN clique.nodes WHERE nid IN acc.neigh)
    THEN
      {
        cliques: acc.cliques + [clique],
        nodes: acc.nodes + clique.nodes,
        neigh: acc.neigh + clique.neighbors
      }
    ELSE acc
  END
) AS accFinal
WITH accFinal.cliques AS disjointCliques

// --- Phase 4: assign pattern_id to chosen cliques ---
UNWIND disjointCliques AS chosen
WITH chosen, randomUUID() AS pid
UNWIND chosen.nodes AS nid
MATCH (n {graph_id: $graph_id}) WHERE id(n) = nid
SET n.pattern_id = pid
RETURN pid, size(chosen.nodes) AS pattern_size
ORDER BY pattern_size DESC;

//WITH collect(A + B) AS allCliques
//RETURN allCliques

// Assign pattern_id if all nodes satisfy the constraint
//CALL {
//  WITH A, B
//  WITH A + B AS allNodes, randomUUID() AS pattern_id
//  UNWIND allNodes AS n
//  SET n.pattern_id = pattern_id
//  RETURN pattern_id
//  LIMIT 1
//}

//RETURN A, B, size(A) + size(B) AS area, pattern_id
//ORDER BY area DESC;

// Remove ALL identity spiders (Z or X, phase 0 mod 2, degree 2) in one
// pass, connecting each one's two neighbors with an edge of the combined
// type: s*s = s, s*h = h, h*h = s. Both edges to the SAME neighbor create
// a self-loop instead: a Hadamard self-loop adds pi to that neighbor, a
// simple self-loop is dropped. Rows are processed sequentially, so the
// preconditions are re-checked per row: an earlier removal can rewire a
// later candidate (identity chains) or flip its phase (self-loop pi).

MATCH (cand:Node {graph_id: $graph_id})
WHERE cand.t IN [1, 2]
  AND cand.phase IS NOT NULL AND cand.phase % 2 = 0
  AND degree(cand) = 2
WITH collect(cand) AS cands
UNWIND cands AS b
MATCH (n1:Node)-[e1:Wire]-(b)-[e2:Wire]-(n2:Node)
WHERE id(e1) < id(e2)
  AND b.phase % 2 = 0 AND degree(b) = 2
  AND n1 <> b AND n2 <> b

WITH b, n1, n2,
     CASE WHEN e1.t = e2.t THEN 1 ELSE 2 END AS new_t

FOREACH (_ IN CASE WHEN n1 <> n2 THEN [1] ELSE [] END |
  CREATE (n1)-[:Wire {t: new_t, graph_id: b.graph_id}]->(n2)
)
FOREACH (_ IN CASE WHEN n1 = n2 AND new_t = 2 THEN [1] ELSE [] END |
  SET n1.phase = (coalesce(n1.phase, 0) + 1) % 2
)

DETACH DELETE b

RETURN count(*) AS identities_removed

// Local complementation: interior Z-spider with phase +-pi/2 (0.5 or 1.5)
// whose every wire is a Hadamard edge to another Z-spider. Removes the spider,
// toggles all Hadamard edges between neighbor pairs and subtracts the spider's
// phase from each neighbor (pyzx lcomp). Applies ONE pattern per call;
// the driver loops until no pattern is left.

MATCH (center:Node {graph_id: $graph_id, t: 1})
WHERE center.phase = 0.5 OR center.phase = 1.5

OPTIONAL MATCH (center)-[w:Wire]-(nbr:Node)
WITH center, collect(DISTINCT nbr) AS neighbors, collect(w) AS wires
WHERE ALL(x IN neighbors WHERE x.t = 1)
  AND ALL(w IN wires WHERE w.t = 2)

WITH center, neighbors
ORDER BY id(center)
LIMIT 1

// Enumerate neighbor pairs; sentinel -1 keeps the row alive when there are
// fewer than two neighbors (UNWIND of an empty list would drop the row and
// the center would never be deleted).
UNWIND (CASE WHEN size(neighbors) >= 2 THEN range(0, size(neighbors) - 2) ELSE [-1] END) AS i
UNWIND (CASE WHEN i >= 0 THEN range(i + 1, size(neighbors) - 1) ELSE [-1] END) AS j
WITH center, neighbors,
     CASE WHEN i >= 0 THEN neighbors[i] END AS n1,
     CASE WHEN j >= 0 THEN neighbors[j] END AS n2

// Toggle: create the Hadamard edge if missing, otherwise collect it for deletion.
OPTIONAL MATCH (n1)-[e:Wire {t: 2}]-(n2)
FOREACH (_ IN CASE WHEN n1 IS NOT NULL AND e IS NULL THEN [1] ELSE [] END |
  CREATE (n1)-[:Wire {t: 2, graph_id: center.graph_id}]->(n2)
)

WITH center, neighbors, collect(e) AS toggled_off
FOREACH (e IN toggled_off | DELETE e)

FOREACH (n IN neighbors |
  SET n.phase = ((coalesce(n.phase, 0) - center.phase) % 2 + 2) % 2
)

DETACH DELETE center

RETURN count(*) AS patterns_processed

// Pivot gadget (pyzx match_pivot_gadget + pivot): interior Pauli Z-spider z_j
// H-connected to an interior NON-Pauli Z-spider z_alpha. Gadgetizes z_alpha's
// phase: a new axis spider (phase = z_j's Pauli phase) H-connected to a new
// tip spider carrying z_alpha's phase; the axis inherits z_j's exclusive and
// shared neighbors. Bipartite edges between the neighbor groups are TOGGLED,
// z_alpha's exclusive neighbors get +z_j, shared get +z_j+pi. Both originals
// are deleted. ONE application per call; the driver loops.
//
// OPTIMIZED: interiorness of z_j and z_alpha is tested with cheap, short-
// circuiting NOT EXISTS predicates, and the O(degree) neighbour-set collection
// runs only for the single chosen pivot (after LIMIT 1) instead of for every
// candidate gadget pair. Without this, on dense graphs the eager collection is
// O(#candidates x degree) and dominates full_reduce.

MATCH (z_j:Node {graph_id: $graph_id, t: 1})-[pe:Wire {t: 2}]-(z_alpha:Node {t: 1})
WHERE z_j.phase IS NOT NULL AND z_alpha.phase IS NOT NULL
  AND z_j.phase % 2 = round(z_j.phase % 2)
  AND z_alpha.phase % 2 <> 0 AND abs(z_alpha.phase % 2) <> 1
  AND degree(z_alpha) > 1
  // z_j interior: every wire Hadamard, every neighbor a Z-spider,
  // and z_j is not a phase-gadget axis (no degree-1 neighbor).
  AND NOT EXISTS { MATCH (z_j)-[w:Wire]-(x:Node) WHERE w.t <> 2 OR x.t <> 1 }
  AND NOT EXISTS { MATCH (z_j)-[:Wire]-(x:Node) WHERE degree(x) = 1 }
  // z_alpha interior.
  AND NOT EXISTS { MATCH (z_alpha)-[w:Wire]-(x:Node) WHERE w.t <> 2 OR x.t <> 1 }
WITH z_j, z_alpha
ORDER BY id(z_j), id(z_alpha)
LIMIT 1

// Collect neighbour groups for the chosen pivot only (both interior, so all
// wires are Hadamard).
OPTIONAL MATCH (z_j)-[:Wire {t: 2}]-(nj:Node)
WHERE nj <> z_alpha
WITH z_j, z_alpha, collect(DISTINCT nj) AS j_nbrs
OPTIONAL MATCH (z_alpha)-[:Wire {t: 2}]-(na:Node)
WHERE na <> z_j
WITH z_j, z_alpha, j_nbrs, collect(DISTINCT na) AS a_nbrs
WITH z_j, z_alpha,
     [x IN j_nbrs WHERE NOT x IN a_nbrs] AS only_j,
     [x IN a_nbrs WHERE NOT x IN j_nbrs] AS only_alpha,
     [x IN j_nbrs WHERE x IN a_nbrs] AS shared

CALL {
  WITH only_j, only_alpha
  UNWIND only_j AS u
  UNWIND only_alpha AS v
  OPTIONAL MATCH (u)-[existing:Wire]-(v)
  FOREACH (_ IN CASE WHEN existing IS NOT NULL THEN [1] ELSE [] END |
    DELETE existing)
  FOREACH (_ IN CASE WHEN existing IS NULL THEN [1] ELSE [] END |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

CALL {
  WITH only_j, shared
  UNWIND only_j AS u
  UNWIND shared AS v
  OPTIONAL MATCH (u)-[existing:Wire]-(v)
  FOREACH (_ IN CASE WHEN existing IS NOT NULL THEN [1] ELSE [] END |
    DELETE existing)
  FOREACH (_ IN CASE WHEN existing IS NULL THEN [1] ELSE [] END |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

CALL {
  WITH only_alpha, shared
  UNWIND only_alpha AS u
  UNWIND shared AS v
  OPTIONAL MATCH (u)-[existing:Wire]-(v)
  FOREACH (_ IN CASE WHEN existing IS NOT NULL THEN [1] ELSE [] END |
    DELETE existing)
  FOREACH (_ IN CASE WHEN existing IS NULL THEN [1] ELSE [] END |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

FOREACH (n IN only_alpha |
  SET n.phase = (coalesce(n.phase, 0) + z_j.phase) % 2)
FOREACH (n IN shared |
  SET n.phase = (coalesce(n.phase, 0) + z_j.phase + 1) % 2)

// Gadgetize: axis takes over z_j (its phase, its exclusive and shared
// neighbors) and is H-connected to the tip carrying z_alpha's phase.
CREATE (axis:Node {t: 1, phase: z_j.phase % 2, graph_id: z_j.graph_id})
CREATE (tip:Node {t: 1, phase: ((z_alpha.phase % 2) + 2) % 2, graph_id: z_j.graph_id})
CREATE (axis)-[:Wire {t: 2, graph_id: z_j.graph_id}]->(tip)
FOREACH (n IN only_j | CREATE (axis)-[:Wire {t: 2, graph_id: z_j.graph_id}]->(n))
FOREACH (n IN shared | CREATE (axis)-[:Wire {t: 2, graph_id: z_j.graph_id}]->(n))

DETACH DELETE z_j, z_alpha

RETURN count(*) AS pivot_operations_performed

// Copy rule (pyzx >= 0.10 copy_simp / rewrite_rules.copy_rule): an arity-1
// spider v with phase 0 or pi is copied through its neighbor w. Across a
// HADAMARD wire the colors must MATCH and the copies get the TOGGLED color;
// across a SIMPLE wire the colors must DIFFER and the copies keep v's color.
// One new spider carrying v's phase is attached to every other wire of w
// (with that wire's type); v and w are deleted. No phases are merged into
// the neighbors (that was the pyzx 0.9 behavior).
// ONE application per call; the driver loops.

MATCH (v:Node {graph_id: $graph_id})-[ve:Wire]-(w:Node)
WHERE v.t IN [1, 2]
  AND degree(v) = 1
  AND v.phase IS NOT NULL
  AND v.phase % 2 = round(v.phase % 2)
  AND w.t IN [1, 2]
  AND ((ve.t = 2 AND w.t = v.t) OR (ve.t = 1 AND w.t <> v.t))

WITH v, w, ve,
     CASE WHEN ve.t = 2 THEN (CASE v.t WHEN 1 THEN 2 ELSE 1 END) ELSE v.t END AS copy_type,
     ((v.phase % 2) + 2) % 2 AS a
ORDER BY id(v)
LIMIT 1

OPTIONAL MATCH (w)-[e:Wire]-(n:Node)
WHERE id(e) <> id(ve)
FOREACH (_ IN CASE WHEN n IS NOT NULL THEN [1] ELSE [] END |
  CREATE (:Node {t: copy_type, phase: a, graph_id: w.graph_id})-[:Wire {t: e.t, graph_id: w.graph_id}]->(n)
)

WITH DISTINCT v, w
DETACH DELETE v, w

RETURN count(*) AS copy_applied

// to_gh step 1 (pyzx to_gh): every wire toggles its type once per X-spider
// endpoint. A wire between two X-spiders toggles twice, i.e. stays put.
// Must run BEFORE the spiders are recolored.

MATCH (a:Node {graph_id: $graph_id})-[w:Wire]->(b:Node)
WITH w,
     (CASE WHEN a.t = 2 THEN 1 ELSE 0 END) +
     (CASE WHEN b.t = 2 THEN 1 ELSE 0 END) AS x_ends
WHERE x_ends % 2 = 1
// Materialize before mutating the indexed wire type.
WITH collect(w) AS wires
UNWIND wires AS w
SET w.t = CASE w.t WHEN 1 THEN 2 ELSE 1 END
RETURN count(*) AS toggled

// Cheap detector: are there any parallel wires between same-colored
// spiders (or any multi-edge at all)? Lets the driver skip the three
// parallel-edge normalization queries when there is nothing to do.
MATCH (a:Node {graph_id: $graph_id})-[r:Wire]-(b:Node)
WHERE id(a) <= id(b)
WITH a, b, count(r) AS c
WHERE c > 1 OR (a = b AND a.t IN [1, 2])
RETURN count(*) AS k

// Batched interior pivot: prune redundant endpoint candidates, then greedily
// retain disjoint closed neighborhoods in estimated toggle-cost order. The first candidate
// always survives, so every nonempty candidate set makes progress. Candidate
// neighborhoods are materialized before any graph mutation.

// Eligibility is unchanged while selecting matches. Mark it once per vertex,
// rather than rechecking the second endpoint's entire neighborhood per edge.
// Clear markers first so an interrupted analytical query is safe to rerun.
CALL {
  MATCH (v:_ZXdbPivotEligible {graph_id: $graph_id})
  REMOVE v:_ZXdbPivotEligible
}
MATCH (v:Node {graph_id: $graph_id, t: 1})
WHERE v.phase IS NOT NULL AND v.phase % 2 = round(v.phase % 2)
  AND NOT EXISTS { MATCH (v)-[w:Wire]-(x:Node) WHERE w.t <> 2 OR x.t <> 1 }
SET v:_ZXdbPivotEligible
WITH count(v) AS tagged
MATCH (a:_ZXdbPivotEligible {graph_id: $graph_id})-[pe:Wire {t: 2}]-(b:_ZXdbPivotEligible)
WHERE id(a) < id(b)
// Keep one candidate per first endpoint before collecting neighborhoods.
// The first retained candidate survives, so this cannot lose progress.
// The closed-neighborhood conflict check below still guarantees independence.
WITH a, b, id(pe) AS rank
ORDER BY degree(a) + degree(b), rank
WITH a, head(collect({b: b, rank: rank})) AS choice
WITH a, choice.b AS b, choice.rank AS rank
// Correlated aggregates keep neighborhood lists out of grouping keys.
CALL {
  WITH a
  OPTIONAL MATCH (a)-[:Wire {t: 2}]-(na:Node)
  RETURN collect(DISTINCT na) AS Na
}
CALL {
  WITH b
  OPTIONAL MATCH (b)-[:Wire {t: 2}]-(nb:Node)
  RETURN collect(DISTINCT nb) AS Nb
}
// Prefer smaller neighborhood products to limit the edge-toggle work.
WITH a, b, rank, Na, Nb ORDER BY size(Na) * size(Nb), rank
WITH collect({a: a, b: b, rank: rank, claim: [a, b] + Na + Nb}) AS P
// Candidate snapshots no longer need the eligibility markers.
CALL {
  MATCH (v:_ZXdbPivotEligible {graph_id: $graph_id})
  REMOVE v:_ZXdbPivotEligible
}

// Greedily retain disjoint closed neighborhoods in estimated toggle-cost order.
// This avoids expanding every candidate into per-vertex claimant rows.
WITH reduce(selected = {used: [], matches: []}, p IN P |
  CASE WHEN any(v IN p.claim WHERE v IN selected.used) THEN selected
       ELSE {used: selected.used + p.claim, matches: selected.matches + [p]} END) AS selected
UNWIND selected.matches AS sv
WITH sv.a AS a, sv.b AS b
CALL {
  WITH a, b
  OPTIONAL MATCH (a)-[:Wire {t: 2}]-(na:Node)
  WHERE na <> b
  RETURN collect(DISTINCT na) AS a_nbrs
}
CALL {
  WITH a, b
  OPTIONAL MATCH (b)-[:Wire {t: 2}]-(nb:Node)
  WHERE nb <> a
  RETURN collect(DISTINCT nb) AS b_nbrs
}
WITH a, b,
     [x IN a_nbrs WHERE NOT x IN b_nbrs] AS only_a,
     [x IN b_nbrs WHERE NOT x IN a_nbrs] AS only_b,
     [x IN a_nbrs WHERE x IN b_nbrs] AS shared

CALL {
  WITH only_a, only_b
  UNWIND only_a AS u
  // Expand each source once, rather than once per potential target.
  CALL {
    WITH u, only_b
    OPTIONAL MATCH (u)-[existing:Wire {t: 2}]-(neighbor)
    WHERE neighbor IN only_b
    RETURN collect(existing) AS existing_edges, collect(neighbor) AS connected
  }
  WITH u, existing_edges, [v IN only_b WHERE NOT v IN connected] AS missing
  FOREACH (edge IN existing_edges | DELETE edge)
  // Simple edges remain; a new parallel H edge is normalized by the caller.
  FOREACH (v IN missing |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

CALL {
  WITH only_a, shared
  UNWIND only_a AS u
  // Expand each source once, rather than once per potential target.
  CALL {
    WITH u, shared
    OPTIONAL MATCH (u)-[existing:Wire {t: 2}]-(neighbor)
    WHERE neighbor IN shared
    RETURN collect(existing) AS existing_edges, collect(neighbor) AS connected
  }
  WITH u, existing_edges, [v IN shared WHERE NOT v IN connected] AS missing
  FOREACH (edge IN existing_edges | DELETE edge)
  // Simple edges remain; a new parallel H edge is normalized by the caller.
  FOREACH (v IN missing |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

CALL {
  WITH only_b, shared
  UNWIND only_b AS u
  // Expand each source once, rather than once per potential target.
  CALL {
    WITH u, shared
    OPTIONAL MATCH (u)-[existing:Wire {t: 2}]-(neighbor)
    WHERE neighbor IN shared
    RETURN collect(existing) AS existing_edges, collect(neighbor) AS connected
  }
  WITH u, existing_edges, [v IN shared WHERE NOT v IN connected] AS missing
  FOREACH (edge IN existing_edges | DELETE edge)
  // Simple edges remain; a new parallel H edge is normalized by the caller.
  FOREACH (v IN missing |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

FOREACH (n IN only_a |
  SET n.phase = (coalesce(n.phase, 0) + b.phase) % 2)
FOREACH (n IN only_b |
  SET n.phase = (coalesce(n.phase, 0) + a.phase) % 2)
FOREACH (n IN shared |
  SET n.phase = (coalesce(n.phase, 0) + a.phase + b.phase + 1) % 2)

DETACH DELETE a, b

RETURN count(*) AS pivot_operations_performed
